package com.example.learnedge.data.diagnostic

import android.content.res.AssetManager
import com.example.learnedge.domain.DiagnosticQuestion
import com.example.learnedge.domain.Track
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext

/** The fixed, hand-written diagnostic quiz. Never generated by the LLM, so it is always reliable. */
class DiagnosticRepository(private val assets: AssetManager) {
    @Volatile private var cached: List<DiagnosticQuestion>? = null

    /** Questions for [track], grouped by skill in the track's skill order. */
    suspend fun questionsFor(track: Track): List<DiagnosticQuestion> {
        val all = cached ?: withContext(Dispatchers.IO) {
            DiagnosticParser.parse(assets.open(ASSET).bufferedReader().use { it.readText() })
        }.also { cached = it }
        val bySkill = all.groupBy { it.skillId }
        return track.skills.flatMap { bySkill[it.id].orEmpty() }
    }

    private companion object {
        const val ASSET = "diagnostic.json"
    }
}
